// Generated from ../4_1.png. Do not edit manually.
const (
	defaultSplashLandscapeWidth  = 1920
	defaultSplashLandscapeHeight = 480
	defaultSplashNativeWidth     = turing88.NativeWidth
	defaultSplashNativeHeight    = turing88.NativeHeight
	defaultSplashRawSize         = 3686400
	defaultSplashCompressedSize  = 2327692
)

var (
	defaultSplashOnce sync.Once
	defaultSplashData []byte
	defaultSplashErr  error
)

func defaultSplashNativeBGRA() ([]byte, error) {
	defaultSplashOnce.Do(func() {
		compressed, err := base64.StdEncoding.DecodeString(strings.Join(defaultSplashBGRACompressedBase64, ""))
		if err != nil {
			defaultSplashErr = err
			return
		}
		if len(compressed) != defaultSplashCompressedSize {
			defaultSplashErr = fmt.Errorf("default splash compressed size mismatch: got %d, want %d", len(compressed), defaultSplashCompressedSize)
			return
		}
		zr, err := gzip.NewReader(bytes.NewReader(compressed))
		if err != nil {
			defaultSplashErr = err
			return
		}
		defer zr.Close()
		data, err := io.ReadAll(zr)
		if err != nil {
			defaultSplashErr = err
			return
		}
		if len(data) != defaultSplashRawSize {
			defaultSplashErr = fmt.Errorf("default splash raw size mismatch: got %d, want %d", len(data), defaultSplashRawSize)
			return
		}
		defaultSplashData = data
	})
	return defaultSplashData, defaultSplashErr
}

